      if (c) { const r = mval('#kl-r'); if (!r) { fieldErr('#kl-r', 'Enter a reason'); return false; } logA('Observation Criteria Library', c.code, 'New version', 'v' + c.version, 'v' + (c.version + 1), r); Object.assign(c, { title: t, desc: mval('#kl-d'), cat: mval('#kl-c'), form, version: c.version + 1 }); }
