critKind = t => { if (!t || S3_CORE.includes(t)) return t; const ty = s3TypeOf(t); return !ty ? t : ty.evidence === S3_EV_K ? 'Knowledge' : ty.evidence === S3_EV_O ? 'Observation' : t; };
critTypeLabel = t => (t && !S3_CORE.includes(t) ? t : t === 'Knowledge' ? 'Knowledge' : 'Observation / Competency');
critTypeNames = cur => (STORE.s3 && STORE.s3.types ? STORE.s3.types.filter(t => t.status === 'Active' || (cur && t.name === cur)).map(t => t.name) : S3_CORE.slice());
const s3Other = t => !!t && !['Knowledge', 'Observation'].includes(critKind(t));
// Criteria keep the governing rule in "type" (so the existing Knowledge / Observation checks apply) and the configured name in "typeName"
const _acS3 = allCrit;
allCrit = function () { return _acS3.apply(this, arguments).map(c => c.type && !S3_CORE.includes(c.type) ? { ...c, typeName: c.type, type: critKind(c.type), evMethod: (s3TypeOf(c.type) || {}).evidence || '' } : c); };
const s3TypeOpts = cur => s3Types().filter(t => t.status === 'Active' || t.name === cur).map(t => `<option value="${esc(t.name)}" ${t.name === cur ? 'selected' : ''}>${esc(t.label || t.name)}${t.status === 'Retired' ? ' (retired)' : ''}</option>`).join('');
const s3TypeChip = t => (t ? critType(t) : '<span class="crit-type">No type</span>');
const s3UsesOf = name => { let n = 0; const scan = tree => (tree || []).forEach(u => u.mods.forEach(m => m.los.forEach(lo => { if (lo.type === name) n++; }))); Object.values(S3().trees).forEach(scan); Object.values(S3().drafts).forEach(d => scan(d.tree)); Object.values(STORE.chProgTree || {}).forEach(scan); return n; };
const s3RetiredPick = (v, cur) => { const ty = s3TypeOf(v); return !!ty && ty.status === 'Retired' && v !== cur; };
const S3_EVID = ['Written assignment questions', 'Workplace observation by an assessor', 'Professional discussion', 'Product evidence', 'Witness testimony'];
function s3TypeDlg(t) { const used = t && !t.core ? s3UsesOf(t.name) : 0, lock = !!(t && (t.core || used)); openModal({ title: t ? 'Edit assessment type' : 'Add assessment type', body: `${used ? `<div class="note b-amber">${ic('lock')}<div class="small">Used by ${plural(used, 'Learning Outcome')} — its name and evidence method can't change. Retire it and add a new type instead.</div></div>` : ''}<div class="field"><label for="ty-n">Name</label><input class="input" id="ty-n" value="${esc(t ? t.name : '')}" ${lock ? 'readonly' : ''}></div><div class="field"><label for="ty-e">Which evidence it uses</label><select class="select" id="ty-e" ${used ? 'disabled' : ''}>${S3_EVID.map(e => `<option ${t && t.evidence === e ? 'selected' : ''}>${e}</option>`).join('')}</select><span class="hint">Written assignment questions follow the Knowledge rules; workplace observation follows the Observation rules. Other methods have no marking workflow yet: a programme that uses them can't be published.</span></div>`,
  actions: [{ label: 'Cancel' }, { label: t ? 'Save' : 'Add type', cls: 'btn-primary', fn: () => { const n = mval('#ty-n'), e = mval('#ty-e'); if (!n) return fieldErr('#ty-n', 'Enter a name'), false; if (s3Types().some(x => x !== t && x.name.toLowerCase() === n.toLowerCase())) return fieldErr('#ty-n', 'This type already exists'), false;
    if (t) { if (used && (n !== t.name || e !== t.evidence)) return fieldErr('#ty-n', 'This type is in use — retire it and add a new type'), false; const was = `${t.name} · ${t.evidence}`; if (!t.core) t.name = n; t.evidence = e; logA('NVQ Programmes', 'Assessment types', 'Assessment type changed', was, `${t.name} · ${e}`, ''); } else { s3Types().push({ id: 'T' + (s3Types().length + 1), name: n, evidence: e, status: 'Active' }); logA('NVQ Programmes', 'Assessment types', 'Assessment type added', '—', `${n} · ${e}`, ''); } render(); } }] }); }
ACT.addType = () => (s3CanEdit() ? s3TypeDlg(null) : s3Refuse('change assessment types', 'Assessment types'));
ACT.s3TypeEdit = el => (s3CanEdit() ? s3TypeDlg(s3Types().find(t => t.id === el.dataset.id)) : s3Refuse('change assessment types', 'Assessment types'));
