const s3Refuse = (what, entity) => { logA('NVQ Programmes', entity, 'Blocked: ' + what, '—', '—', 'Role can\'t ' + what); toast('You can\'t ' + what + '.', 'err'); return false; };
const s3Guard = pr => { if (!pr || pr.chNew) return false; if (!s3CanEdit()) return s3Refuse('change the structure', `${pr.title} (${pr.id})`); if (pr.status === 'Retired') { toast('Retired programmes can\'t be changed.', 'err'); return false; } return true; };
