    const t = mval('#nd-t'); if (!t) return fieldErr('#nd-t', 'Enter a title'), false;
    const tree = s3EditTree(pr.id, true, lvl === 'lo' && s3Other(mval('#nd-y'))), n = s3Find(tree, d.u, d.m, d.lo); let what;
    if (lvl === 'unit') { const c = mval('#nd-c').toUpperCase(); if (!/^U\d{3}$/.test(c)) return fieldErr('#nd-c', 'Use the format U308'), false; if (s3AllCodes(tree).includes(c)) return fieldErr('#nd-c', 'This code is already used in this programme'), false; tree.push({ code: c, title: t, status: 'Active', mods: [] }); what = `${c} ${t}`; }
    if (lvl === 'mod') { const ab = mval('#nd-ab'); if (ab && !/^[A-Z]\/\d{3}\/\d{4}$/.test(ab)) return fieldErr('#nd-ab', 'Use the format T/652/0001'), false; const code = 'M' + (n.u.mods.length + 1); n.u.mods.push({ code, title: t, ab, status: 'Active', los: [] }); what = `${d.u} ${code} ${t}`; }
