    if (lvl === 'crit') { const code = `${d.u.slice(1)} ${n.lo.code.replace(/\D/g, '')}.${n.lo.crit.length + 1}`; if (s3AllCodes(tree).includes(code)) return fieldErr('#nd-t', 'The next code is already used — rename an existing criterion first'), false; n.lo.crit.push({ code, d: t, evReq: mval('#nd-e') || 'Written evidence that addresses every part of the descriptor', status: 'Active' }); what = `${code} ${t}`; }
