  if (pr.status === 'Draft') return `<div class="note b-amber s3-vh">${ic('alert')}<div class="small"><strong>Draft programme.</strong> Publishing is checked against this programme's own structure: every Learning Outcome needs an assessment type.</div></div><div class="row"><button class="btn btn-primary" data-act="kPubProg" data-id="${pr.id}">Publish programme</button></div>`;
  if (dv) return `<div class="note b-amber s3-vh">${ic('layers')}<div class="small"><strong>You're editing Version ${dv.v} (draft).</strong> Learners stay on Version ${pr.version} until it's published. Publishing makes it the version for new batches and sign-ups.</div></div><div class="row"><button class="btn btn-primary" data-act="kPubProg" data-id="${pr.id}">Publish version ${dv.v}</button>${chip('Version ' + dv.v + ' draft', 'amber')}</div>`;
  return `<div class="note b-blue s3-vh">${ic('layers')}<div class="small"><strong>Version ${pr.version} is current.</strong> To change the structure, create a new version: a draft copy you edit, then publish. Nothing changes for learners until then.</div></div>${tab === 'versions' ? '' : `<div class="row"><button class="btn" data-act="newProgVersion" data-id="${pr.id}">Create new version</button></div>`}`;
