  const card = `<section class="card s3-wver"><div class="row-b"><h2>Versions</h2>${pr.nextDraft ? `<button class="btn btn-sm btn-primary" data-act="s3WizPublish" data-id="${pr.id}">Publish version ${pr.version + 1}</button>` : `<button class="btn btn-sm" data-act="s3WizVersion" data-id="${pr.id}">Create new version</button>`}</div><p class="small muted">${pr.nextDraft ? `You're editing Version ${pr.version + 1} (draft) on the Structure step. Learners stay on Version ${pr.version} until it's published.` : `Version ${pr.version} is current. A new version lets you change the structure.`}</p></section>`;
  const k = h.indexOf('<ol class="stepper ch8-steps">'); return k < 0 ? h + card : h.slice(0, k) + card + h.slice(k);
