ACT.s3WizVersion = el => { const pr = s3Pr(el.dataset.id); if (!pr || pr.nextDraft) return; reasonDlg({ title: 'Create new version', ok: `Create Version ${pr.version + 1} (draft)`, body: '<p class="small">The structure becomes editable as a draft; learners stay on the current version.</p>', onOk: r => { s3Hist(pr); s3Snap(pr)[pr.version] = JSON.parse(JSON.stringify(ch8Tree(pr.id))); pr.nextDraft = true; s3Log(pr, 'Version created (draft)', 'Version ' + pr.version, `Version ${pr.version + 1} (draft)`, r); go('a-programmes', { id: pr.id, tab: 'structure' }); } }); };
