// Structure step with Rename and (Draft only) Remove
ch8StructureStep = function (pr) {
  const t = ch8Tree(pr.id), ed = s3WizEd(pr), draftProg = pr.status === 'Draft', d = v => `data-id="${pr.id}" ${Object.entries(v).map(([a, b]) => `data-${a}="${b}"`).join(' ')}`;
  const tools = (o, can) => ed ? `<button class="btn btn-sm btn-ghost" data-act="s3WRename" ${d(o)}>Rename</button>${draftProg ? `<button class="btn btn-sm btn-ghost" data-act="s3WRemove" ${d(o)}>Remove</button>` : ''}` : '';
  return `<section class="card"><div class="row-b"><h2>Structure${pr.nextDraft ? ` — Version ${pr.version + 1} (draft)` : ''}</h2>${ed ? `<button class="btn btn-sm btn-primary" data-act="ch8AddUnit" data-id="${pr.id}">${ic('plus', 14)}Add unit</button>` : ''}</div>
    <p class="small muted">Programme → Unit → Module (awarding-body code) → Learning Outcome (assessment type from the governed list — required before publishing) → Assessment Criterion (descriptor and evidence requirements). An answer key per module is optional.${draftProg ? ' While the programme is a Draft, nodes can be removed.' : ' Nodes are never removed after publishing.'}</p>
    ${t.length ? `<div class="tree ch8-tree">${t.map((u, ui_) => `<details class="lvl-1" open><summary><span class="caret">${ic('chev', 16)}</span><span class="tw"><span class="strong"><span class="code">${esc(u.code)}</span> ${esc(u.title)}</span></span>${tools({ u: ui_ })}${ed ? `<button class="btn btn-sm" data-act="ch8AddMod" ${d({ u: ui_ })}>${ic('plus', 13)}Module</button>` : ''}</summary><div class="kids">${u.mods.map((m, mi) => `<details open><summary><span class="caret">${ic('chev', 16)}</span><span class="tw small strong"><span class="code">${m.code}</span> ${esc(m.title)} <span class="mono xs muted">(${esc(m.ab)})</span></span>${m.key ? chip('Answer key', 'blue') : ''}${tools({ u: ui_, m: mi })}${ed ? `<button class="btn btn-sm btn-ghost" data-act="ch8Key" ${d({ u: ui_, m: mi })}>${m.key ? 'Replace answer key' : 'Answer key (optional)'}</button><button class="btn btn-sm" data-act="ch8AddLo" ${d({ u: ui_, m: mi })}>${ic('plus', 13)}Learning Outcome</button>` : ''}</summary><div class="kids">${m.los.map((lo, li) => `<div class="ch8-lo"><div class="row-b"><span class="small"><span class="code">${lo.code}</span> ${esc(lo.title)}</span><span class="row" style="gap:6px">${ed ? `<label class="sr" for="lt-${ui_}-${mi}-${li}">Assessment type for ${lo.code}</label><select class="select" id="lt-${ui_}-${mi}-${li}" data-onchange="ch8LoType" ${d({ u: ui_, m: mi, l: li })}><option value="" ${!lo.type ? 'selected' : ''}>No type yet</option>${critTypeNames(lo.type).map(x => `<option value="${esc(x)}" ${x === lo.type ? 'selected' : ''}>${esc(x)}${s3TypeOf(x) && s3TypeOf(x).status === 'Retired' ? ' (retired)' : ''}</option>`).join('')}</select>` : chip(lo.type || 'No type', lo.type ? 'blue' : 'red')}${!lo.type ? chip('Type required', 'red') : ''}${tools({ u: ui_, m: mi, l: li })}${ed ? `<button class="btn btn-sm btn-ghost" data-act="ch8AddCrit" ${d({ u: ui_, m: mi, l: li })}>${ic('plus', 13)}Criterion</button>` : ''}</span></div>
      ${lo.crit.length ? `<ul class="list small">${lo.crit.map((c, ci) => `<li class="li"><span class="code">${esc(c.code)}</span><div class="li-b">${esc(c.d)}<span class="xs muted">Evidence: ${esc(c.ev)}</span></div>${tools({ u: ui_, m: mi, l: li, c: ci })}</li>`).join('')}</ul>` : '<p class="xs muted">No criteria yet.</p>'}</div>`).join('') || '<p class="xs muted">No Learning Outcomes yet.</p>'}</div></details>`).join('') || '<p class="xs muted">No modules yet.</p>'}</div></details>`).join('')}</div>` : '<div class="empty"><p class="small">No units yet. Add the first unit.</p></div>'}</section>`;
};
const s3WNode = (pr, d) => { const u = ch8Tree(pr.id)[+d.u], m = d.m != null && u ? u.mods[+d.m] : null, lo = d.l != null && m ? m.los[+d.l] : null, c = d.c != null && lo ? lo.crit[+d.c] : null; return { u, m, lo, c, node: c || lo || m || u, key: c ? 'd' : 'title' }; };
ACT.s3WRename = el => { const pr = s3Pr(el.dataset.id); if (!pr || !s3WizEd(pr)) return; const n = s3WNode(pr, el.dataset); openModal({ title: 'Rename', body: `<div class="field"><label for="wr-t">${n.c ? 'Descriptor' : 'Title'}</label><input class="input" id="wr-t" value="${esc(n.node[n.key])}"></div>`, actions: [{ label: 'Cancel' }, { label: 'Rename', cls: 'btn-primary', fn: () => { const t = mval('#wr-t'); if (!t) return fieldErr('#wr-t', 'Enter a title'), false; if (t === n.node[n.key]) return fieldErr('#wr-t', 'Nothing has changed'), false; const was = n.node[n.key]; n.node[n.key] = t; ch8Log(pr, 'Node renamed', was, t); render(); } }] }); };
