INP.ch8LoType = el => { const pr = ch8Pr(el.dataset.id), n = pr && ch8Find(pr, +el.dataset.u, +el.dataset.m, +el.dataset.l); if (n && n.lo && s3RetiredPick(el.value, n.lo.type)) { toast('Retired types can\'t be chosen for Learning Outcomes.', 'err'); render(); return; } return _ch8LoTypeS3(el); };
const _ch8CheckS3 = ch8Check;
ch8Check = function (pr) { const r = _ch8CheckS3.apply(this, arguments), o = ch8Los(pr.id).filter(x => s3Other(x.lo.type)).map(x => `${x.u.code} ${x.m.code} ${x.lo.code} (${x.lo.type} — evidence: ${((s3TypeOf(x.lo.type) || {}).evidence || 'not set').toLowerCase()})`); if (o.length) r.block.push('Assessment method not supported yet — learners couldn\'t complete: ' + o.join('; ') + '. Change the type to publish'); return r; };

/* ---------- New sign-ups and new batches use the programme's current published version ---------- */
// A learner copy of a programme's structure (criteria start Not Started; nothing from other learners)
// Published structure of a wizard programme's version v. While a new version is a draft, the live tree holds the draft edits,
// so the version being replaced is kept as a snapshot when the draft is created. Unknown versions → null (never guessed).
const s3Snap = pr => ((S3().snap = S3().snap || {})[pr.id] = S3().snap[pr.id] || {});
const s3PubTree = (pr, v) => s3Snap(pr)[v] || (v === pr.version ? (pr.chNew ? (pr.nextDraft ? null : ch8Tree(pr.id)) : s3Tree(pr.id)) : null); // S4a: Level 2–5 too (their drafts are kept apart)
const s3LearnerTree = tree => tree.filter(u => u.status !== 'Retired').map(u => ({ code: u.code, title: u.title, mods: u.mods.filter(m => m.status !== 'Retired').map(m => ({ code: m.code, title: m.title, ab: m.ab || '', los: m.los.filter(l => l.status !== 'Retired').map(lo => ({ code: lo.code, title: lo.title, type: lo.type, crit: lo.crit.filter(c => c.status !== 'Retired').map(c => ({ code: c.code, d: c.d, evReq: c.evReq || c.ev || '', st: 'Not Started' })) })) })) }));
