ch8StartSignup = function (w, pr) { const had = !!w.tree, r = _suS3.apply(this, arguments); if (!had && pr) { w.tree = s3LearnerTree(s3PubTree(pr, pr.version) || []); w.assignments = []; w.nvq.version = 'Version ' + pr.version; w.nvq.progVersion = pr.version; logA('Admissions', `${chFullName(w)} (${w.me.id})`, 'Programme version assigned', '—', `${pr.title} — Version ${pr.version}`, 'Sign-up started'); } return r; };
// Batches record the programme version they were created on (batches that existed before are not back-filled)
const s3BatchVer = b => (b && b.progVersion ? b.progVersion : null);
const _sybS3 = typeof syncTasBatches === 'function' ? syncTasBatches : null;
let s3BatchBefore = null; // batch codes when "Create batch" was opened
const _nbS3 = ACT.newBatch; ACT.newBatch = function () { s3BatchBefore = (ADMIN.batches || []).map(b => b.code); return _nbS3.apply(this, arguments); };
if (_sybS3) syncTasBatches = function () { (ADMIN.batches || []).forEach(b => { if (b.progVersion || !s3BatchBefore || s3BatchBefore.includes(b.code)) return; const pr = s3Progs().find(p => p.title === b.course); if (pr) { b.progVersion = pr.version; logA('Batches', b.code, 'Programme version recorded', '—', `${pr.title} — Version ${pr.version}`, 'Batch created'); } }); return _sybS3.apply(this, arguments); };

const _bdS3 = batchDetail;
batchDetail = function (code) { const h = _bdS3.apply(this, arguments), b = ADMIN.batches.find(x => x.code === code), v = s3BatchVer(b), k = h.indexOf('<div class="subtabs"'); if (!v || k < 0) return h; return h.slice(0, k) + `<p class="small s3-bver">${ic('layers', 14)} Programme version: <strong>Version ${v}</strong> — recorded when the batch was created. Sign-ups enrolled in it start on this version.${(m => m.length ? ' ' + plural(m.length, 'learner') + ' with a recorded version: ' + m.map(w => esc(chFullName(w)) + ' (Version ' + w.nvq.progVersion + ')').join(', ') + '.' : '')(s3LearnersOf(b))}</p>` + h.slice(k); };

// At enrolment (sign-up complete) the learner's version is fixed: the batch's recorded version when it has one, otherwise
// the current published version (batches created before versions were recorded are not back-filled). Never changed afterwards.
const _ccS3 = chComplete;
chComplete = function (w) { const r = _ccS3.apply(this, arguments); s3PinVersion(w); return r; };
function s3PinVersion(w) {
  const pr = w && w.signup && w.signup.prog && w.signup.done && ch8Pr(w.signup.prog); if (!pr || w.nvq.s3Pinned) return;
  const b = ADMIN.batches.find(x => x.code === w.signup.batch), bv = s3BatchVer(b), bt = bv ? s3PubTree(pr, bv) : null, v = bt ? bv : pr.version;
  w.tree = s3LearnerTree(bt || s3PubTree(pr, pr.version) || []); w.nvq.version = 'Version ' + v; w.nvq.progVersion = v; w.nvq.s3Pinned = true;
  logA('Admissions', `${chFullName(w)} (${w.me.id})`, 'Programme version fixed at enrolment', '—', `${pr.title} — Version ${v}`, b ? (bv ? `Batch ${b.code} recorded Version ${bv}` : `Batch ${b.code} has no recorded version — current published version`) : 'No batch — current published version');
}
const s3LearnersOf = b => Object.values(STORE.worlds || {}).filter(w => w.signup && w.signup.done && w.signup.batch === b.code && w.nvq && w.nvq.progVersion);

/* ---------- Scenario #28 ---------- */
const s3AsSA = () => { setAdminIdentity('A'); S.portal = 'admin'; S.signedIn = true; };
ACT.s3Sc28Ver = () => { s3AsSA(); go('a-programmes', { id: 'NV-L3', tab: 'versions' }); if (!s3Draft('NV-L3')) ACT.newProgVersion({ dataset: { id: 'NV-L3' } }); };
ACT.s3Sc28Edit = () => { s3AsSA(); const pr = s3Pr('NV-L3'); if (!s3Draft('NV-L3')) s3NewVersion(pr, 'Scenario #28', true); const t = s3Draft('NV-L3').tree;
  if (!t.some(u => u.code === 'U308')) { t.push({ code: 'U308', title: 'Health and safety in care settings', status: 'Active', mods: [{ code: 'M1', title: 'Safe practice', ab: 'T/652/0801', status: 'Active', los: [{ code: 'LO1', title: 'Understand health and safety duties', type: 'Knowledge', status: 'Active', crit: [{ code: '308 1.1', d: 'Explain the main health and safety duties of a care worker', evReq: 'Written evidence that addresses every part of the descriptor', status: 'Active' }] }] }] }); s3Log(pr, 'Node added', '—', 'U308 Health and safety in care settings', 'Version ' + s3Draft('NV-L3').v + ' (draft) — Scenario #28'); }
  go('a-programmes', { id: 'NV-L3', tab: 'tree' }); toast('Demo: U308 added to the draft version.', 'info'); };
ACT.s3Sc28Pub = () => { if (!s3Draft('NV-L3')) ACT.s3Sc28Edit(); s3AsSA(); go('a-programmes', { id: 'NV-L3', tab: 'versions' }); ACT.kPubProg({ dataset: { id: 'NV-L3' } }); };
ACT.s3Sc28Learner = () => { S.variant = 'C'; ACT.switchRole({ dataset: { r: 'learner' } }); S.signedIn = true; go('progress'); toast('Aisha Rahman stays on her version — her units are unchanged.', 'info'); };
ACT.s3Sc28Obs = () => { const c = s3Lib().find(x => x.code === 'IA-5'); if (c) { c.form = true; if (!c.progs.includes('NV-L3')) c.progs.push('NV-L3'); s3SyncIA(); } S.tas.v = 'A'; tasEnter(); S.signedIn = true; go('t-obs'); ACT.obPropose({ dataset: {} }); toast('Demo: IA-5 ticked "On observation forms" and attached to Level 3 — it is on the observation form.', 'info'); };
const _scListS3 = SC_LIST;
SC_LIST = function () {
  const x = (text, r, t, act) => ({ text, r, t, act });
  return _scListS3().concat([['28', 'Change a programme\'s structure with a new version', 'Setup S3', [
    x('The Super Admin opens Level 3 → Versions and chooses "Create new version" — a draft copy of the current structure.', 'admin', 'a-programmes.NV-L3.versions', 's3Sc28Ver'),
    x('In the Hierarchy builder, a unit is added to the draft (U308 Health and safety).', 'admin', 'a-programmes.NV-L3.tree', 's3Sc28Edit'),
    x('"Publish version 3" — checked against the draft\'s own structure.', '', '', 's3Sc28Pub'),
    x('Aisha Rahman stays on her version: her progress shows the same units.', '', '', 's3Sc28Learner'),
    x('In the Observation Criteria Library, IA-5 is ticked "On observation forms" and attached to Level 3 — the assessor\'s observation form lists it.', 'staff', 't-obs', 's3Sc28Obs')]]]);
};
CDL_SCEN.push(['28', 'Change a programme\'s structure with a new version', 'Setup fixes (S3)']);
['Twenty-eight'].forEach(w => { if (!CH_NUMW.includes(w)) CH_NUMW.push(w); });

/* ---------- Records ---------- */
UXC.push(['Setup S3', 'Setup fixes — NVQ programmes: structure, versions, library, types (S3-01 … S3-07)', [
  'S3-01: each programme has its own structure tree — Level 3 is Aisha\'s tree exactly as before, Level 2 is Grace\'s, Level 4 and Level 5 have three units each, the retired 2018 spec a copy of Level 3, and the 2027 update (NV-L3D) Level 3 plus U310 and U311. Module codes and answer keys are stored per programme.',
  'S3-02: the Hierarchy builder really adds units, modules, Learning Outcomes and criteria ("Add unit" and "+"), renames, moves (units and modules up/down; Learning Outcomes between modules, with the evidence preview) and suspends / retires nodes — audited, never deleted. A programme with learners gets these changes in a draft version (created on the first change). The new-programme wizard also renames, and removes nodes while the programme is a Draft.',
  'S3-03: "Create new version" makes a real draft copy that is edited and published ("Publish version N"); learners stay on their version. Wizard-made programmes can start a new version after publishing too.',
  'S3-04: NV-L3D\'s "Publish programme" checks its own tree (Learning Outcomes without a type block; uncovered criteria warn) — no hard-coded list.',
  'S3-05: one observation-criteria library (also in the Super Admin\'s Academic menu). IA-1–IA-4 keep their observation-form meaning; the Academic page\'s own entries were re-coded IA-7 onwards; IA-5 and IA-6 added. Add, edit (new version), Activate (Draft → Active), retire and "Attach to scope" all work, and active criteria ticked "On observation forms" and attached to a programme appear on its observation forms.',
  'S3-06: assessment types — "Add type" (name, which evidence it uses), edit and retire; Knowledge and Observation can\'t be retired. Active types appear in the Learning Outcome type list. S3-07: an answer key can be removed (kept in the history); learners no longer see it.',
  'S2 follow-up: the assignment\'s "Assigned marker" field is now a read-only line — "Marked by: [the batch\'s assignment assessor], set in the batch\'s Assessors panel" (CH-17).']]);
UXC.push(['Setup S3', 'Setup fixes — S3 acceptance corrections (A–E)', [
  'A — custom assessment types. Problem: learner screens showed any custom type as "Observation / Competency". Files: core.js (critType reads critTypeLabel; new critTypeNames / critKind hooks), setup-s3.js (allCrit keeps the governing rule in "type" and the configured name in "typeName"), screens-b.js, staff.js, coord.js, iqa.js, clientsheet.js (show typeName), setup-s2.js (mapping uses the rule; linked criteria keep the name). Source: S3-06. Now: the configured name is shown on learner, assessor and admin screens; Knowledge and Observation are unchanged; a type whose evidence is written assignment questions follows the Knowledge rules (mappable to assignments), one whose evidence is workplace observation follows the Observation rules. Other evidence methods (professional discussion, product evidence, witness testimony) get no marking workflow, so publishing is blocked (client decision after S3 review): the Hierarchy builder and the new-programme wizard name each affected Learning Outcome and its type; drafts stay editable, and choosing such a type on a published programme always opens a draft version. A type in use can\'t be renamed or change its evidence method (retire it and add a new one; client decision); historical records keep showing the original type. Tests: ft-setup "S3 correction A" (positive and negative).',
  'B — wizard type list. Problem: the new-programme wizard offered only Knowledge and Observation. Files: ch-b8.js (ch8TypeSel uses critTypeNames), setup-s3.js (Structure step select; INP.ch8LoType refuses retired types; ch8Check blocks types with no marking workflow). Source: S3-06. Now: the wizard and the Hierarchy builder use the same governed list — every active type; retired types are not offered, but a Learning Outcome that already uses one keeps it (shown "(retired)"). The type persists through save, reopen, new version and publish, and criteria inherit it. Tests: ft-setup "S3 correction B".',
  'C — Letter and Support type tabs. Problem: the older header showed "Publish version N" with no draft to publish. File: setup-s3.js (one header, s3VerHeader, on every builder tab). Source: S3-03. Now: Draft programme → "Publish programme"; a draft version → "You\'re editing Version N (draft)" and "Publish version N"; otherwise "Version N is current" and "Create new version" (a draft copy — nothing is published until "Publish version N"); Retired → read-only. Version protections are unchanged. Tests: ft-setup "S3 correction C".',
  'D — Move impact preview. Problem: the preview used Level 3\'s assignments and counted every learner with the same criterion code, so Level 2 judgements showed on Level 3 and other programmes always showed zero. File: setup-s3.js (s3LoEvidence). Source: G6.5 / S3-02. Now: counts come from the selected programme\'s own learners and assignments; a programme with no evidence says so ("No learner evidence on this programme"). Tests: ft-setup "S3 correction D".',
  'E — version history. Problem: earlier versions were given invented dates and an author. File: setup-s3.js. Source: S3-03. Now: versions that existed before the prototype\'s audit trail are shown as "Demo fixture" with no date or author; a wizard programme\'s Version 1 uses its recorded publish date; creating and publishing versions add real entries (who, when, reason) and the Versions tab shows the audit rows. Tests: ft-setup "S3 correction E".',
  'Version consistency: a sign-up to a programme made with the wizard gets its published structure — never unpublished draft edits (the version being replaced is kept when a new version starts); at enrolment the learner\'s version is fixed to the batch\'s recorded version, or the current published version for batches created before versions were recorded. Learners are never migrated automatically and existing demo batches are not back-filled. Tests: ft-setup "S3 decision 1" and "S3 version consistency".',
  'Also: a sign-up to a programme made with the wizard now gets that programme\'s structure (it got a copy of Level 3\'s before); batches created from now on record the programme version they were created on (shown on the batch page; existing batches are not back-filled); structure, type and library changes by other roles are refused and logged. Tests: ft-setup "S3 end to end" (13 workflows) and "S2 / CH-17 marker".',
  'Remaining limits (accepted): sign-ups to Level 2 / Level 3 still switch to demo learner B (no new learner record; no registration refactor in S3), so the version-at-enrolment rule is shown only for programmes made with the wizard. Earlier versions of Level 2 / Level 3 / Level 4 / Level 5 are not stored as structures (their learners keep their own copy). Academy observation criteria apply per programme, not per batch. The TBD register is unchanged.']]);
const _aIdxS3 = SCREENS['a-index'];
SCREENS['a-index'] = p => _aIdxS3(p).replace(/(<section class="card idx-sec"><h2>Setup fixes<\/h2><ul class="idx-list">)/, `$1${[
  chIdxLi('NVQ programme → Hierarchy builder (Level 4)', { act: 'aJump', t: 'a-programmes.NV-L4.tree' }, 'S3-01 / S3-02 — the programme\'s own structure; add, rename, move, suspend.'),
  chIdxLi('NVQ programme → Versions (Level 3)', { act: 'aJump', t: 'a-programmes.NV-L3.versions' }, 'S3-03 — create, edit and publish a new version.'),
  chIdxLi('Draft programme NV-L3D → Publish check', { act: 'aJump', t: 'a-programmes.NV-L3D.tree' }, 'S3-04 — publishing checks the programme\'s own tree.'),
  chIdxLi('Observation Criteria Library (one list)', { act: 'aJump', t: 'k-obslib' }, 'S3-05 — one library; it drives the observation forms.'),
  chIdxLi('NVQ programme → Assessment types', { act: 'aJump', t: 'a-programmes.NV-L3.types' }, 'S3-06 — add, edit and retire types.'),
  chIdxLi('Demo Scenario #28', { act: 'scOpen' }, 'S3 — a new version end to end, and the library on the observation form.')].join('')}`);

if (typeof ADMIN !== 'undefined' && ADMIN && STORE.worlds) s3Init();
